  "parecer": "sustentada",
  "tipo_efeito": "parametro_contratual",
  "aspectos": {
    "entidade": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D02",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D02 identifica SUP_MOTOR como o objeto da nova disponibilidade contratada; N.SUP_MOTOR identifica SUP_MOTOR como o fornecedor MotorTech.",
      "contexto_ids": []
    },
    "alvo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D02",
        "N.SUP_MOTOR"
      ],
      "justificativa": "N.SUP_MOTOR caracteriza a disponibilidade contratada do fornecedor e registra a restrição local de não iniciar antes de D18. CHANGE.D02 comunica a nova disponibilidade contratada para SUP_MOTOR, sustentando a atualização do alvo release_SUP_MOTOR, não uma duração da atividade."
      ,
      "contexto_ids": []
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D02",
        "N.SUP_MOTOR"
      ],
      "justificativa": "A fonte de plano distingue disponibilidade contratada de duração da atividade; o evento altera a disponibilidade contratada. Assim, há suporte para o atributo valor da restrição local, e não para substituir a duração."
      ,
      "contexto_ids": []
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D02",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D02 expressa a nova disponibilidade em dias corridos; N.SUP_MOTOR também expressa a restrição local em dias corridos."
      ,
      "contexto_ids": []
    },
    "valor": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D02",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D02 afirma diretamente que a nova disponibilidade contratada é de 25 dias corridos desde D0. N.SUP_MOTOR confirma que, para o fornecedor, disponibilidade contratada é o parâmetro pertinente; seu valor anterior D18 não contradiz a nova afirmação."
      ,
      "contexto_ids": []
    },
    "condicoes": {
      "estado": "nao_aplicavel",
      "fonte_ids": [],
      "justificativa": "A proposta não declara condições de aplicação.",
      "contexto_ids": []
    },
    "escopo": {
      "estado": "sustentado",
      "fonte_ids": [
        "CHANGE.D02"
      ],
      "justificativa": "O cadastro verificado vincula D02 ao projeto ALFA-AMPLIADO, versão 1.0.0, com vigência prospectiva desde o dia 0 e sem fim declarado. A referência a disponibilidade desde D0 em CHANGE.D02 é compatível com esse início; não há restrição documental divergente.",
      "contexto_ids": [
        "CONTEXTO.ESCOPO"
      ]
    }
  },
  "fontes_examinadas": [
    "CHANGE.D02",
    "E001",
    "N.SUP_MOTOR",
    "P.p_10"
  ],
  "justificativa": "A afirmação direta de nova disponibilidade contratada de 25 dias corridos desde D0 sustenta a substituição do valor da restrição local de SUP_MOTOR. N.SUP_MOTOR esclarece que a disponibilidade contratada do fornecedor corresponde ao parâmetro em questão, enquanto a duração da atividade é zero. E001 registra apenas precedência para C_MOTOR e não é usada para propagar ou alterar a restrição de SUP_MOTOR; P.p_10 trata de uma parcela contratual sem relação com esta proposta. O escopo cadastrado está verificado e é compatível com a referência temporal do evento.",
  "suporte_ausente": [],
  "contextos_examinados": [
    "CONTEXTO.ESCOPO"
  ],
  "fundamentos_valor": {
    "valor": {
      "conhecimento": "exato",
      "valores": [
        25
      ],
      "fonte_ids": [
        "CHANGE.D02",
        "N.SUP_MOTOR"
      ],
      "justificativa": "CHANGE.D02 afirma 25 dias corridos desde D0 como nova disponibilidade contratada. N.SUP_MOTOR identifica essa disponibilidade como o parâmetro do fornecedor, distinguindo-a de sua duração.",
      "aplicabilidade": "mesmo_objeto_e_vigencia"
    }
  },
  "restricoes_escopo": [
    {
      "conhecimento": "exato",
      "valores": [
        0
      ],
      "fonte_ids": [
        "CHANGE.D02"
      ],
      "justificativa": "A expressão “desde D0” declara o início temporal da nova disponibilidade no dia 0, compatível com a vigência prospectiva cadastrada.",
      "campo": "inicio_dia"
    }
  ]
}
